SELECT id_ AS id, type, data, time_limite AS timeLimite, statistics_date AS statisticsDate, area_type AS areaType
FROM topp_oppotunity_statistics_test
--         FROM topp_oppotunity_statistics
WHERE type = #{type}
AND statistics_date = #{date}
AND area_type = #{areaType}

    AND time_limite = #{timeLimite}

LIMIT 1
